/* Get the EGTM_GENERIC APP version. */
ACS_APP_VERSION_t EGTM_GENERIC_GetAppVersion()
{
  ACS_APP_VERSION_t version;

  version.major = EGTM_GENERIC_MAJOR_VERSION;
  version.minor = EGTM_GENERIC_MINOR_VERSION;
  version.patch = EGTM_GENERIC_PATCH_VERSION;

  return version;
}

/* Function to initialize the EGTM clock frequencies and trigger connections. */
EGTM_GENERIC_STATUS_t EGTM_GENERIC_Init(EGTM_GENERIC_t * handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));
  Ifx_EGTM *egtm = handle->app_config->egtm_module;

  if (!handle->app_is_initialized)
  {
    uint32 mask = 0;
    uint32 shift = 0;

    /* Enable EGTM, it is necessary if the EGTM is not initialized earlier */
    IfxEgtm_enable(egtm);

    /* Set EGTM cluster clock divider to 1 when it is needed */
    uint32 egtmFreqHalf = IfxClock_geteGtmFrequency() / 2;
    if ((uint32)handle->app_config->cmu.gclk > egtmFreqHalf)
    {
      IfxEgtm_setResetProtection(FALSE);
      IfxEgtm_setClusterClockDiv(IfxEgtm_Cluster_0, IfxEgtm_ClusterClockDiv_enable);
      IfxEgtm_setClusterClockDiv(IfxEgtm_Cluster_1, IfxEgtm_ClusterClockDiv_enable);
      IfxEgtm_setClusterClockDiv(IfxEgtm_Cluster_2, IfxEgtm_ClusterClockDiv_enable);
      IfxEgtm_setResetProtection(TRUE);
    }

    /* Set the EGTM global clock frequency */
    IfxEgtm_Cmu_setGclkFrequency(egtm, handle->app_config->cmu.gclk);

    /* Set the EGTM configurable clock frequency */
    for (uint8 i = 0; i < EGTM_GENERIC_CMU_CLK_NUMBER ; i++)
    {
      if (handle->app_config->cmu.clk_en[i])
      {
        IfxEgtm_Cmu_setClkFrequency(egtm, i, handle->app_config->cmu.clk[i]);
        mask = mask | (EGTM_GENERIC_CMU_CLK_EN_MSK_LEN << shift);
      }
      shift += 2;
    }

    /* Set the EGTM external clock frequency */
    for (uint8 i = 0; i < EGTM_GENERIC_CMU_ECLK_NUMBER ; i++)
    {
      if (handle->app_config->cmu.eclk_en[i])
      {
        IfxEgtm_Cmu_setEclkFrequency(egtm, i, handle->app_config->cmu.eclk[i]);
        mask = mask | (EGTM_GENERIC_CMU_CLK_EN_MSK_LEN << shift);
      }
      shift += 2;
    }

    if (handle->app_config->cmu.fxclk_en)
    {
      mask = mask | (EGTM_GENERIC_CMU_CLK_EN_MSK_LEN << shift);
    }

    /* Enable the required clocks */
    IfxEgtm_Cmu_enableClocks(egtm, mask);

    /* Configures the tout selection */
    for (uint32 i = 0; i < handle->app_config->toutsel.num; i++)
    {
      IfxEgtm_Tom_setTout(handle->app_config->toutsel.conf[i].tout_num, handle->app_config->toutsel.conf[i].tout_sel);
    }

    /* Configures the adc_out0 selection */
    for (uint32 i = 0; i < handle->app_config->adc_out0.num; i++)
    {
      uint32 shift   = (handle->app_config->adc_out0.conf[i].adc_out0_num & 0x3U) * EGTM_GENERIC_ADC_OUT_SEL_LEN;
      uint32 value   = handle->app_config->adc_out0.conf[i].adc_out0_sel << shift;
      uint32 mask    = 0xFFU << shift;
      Ifx__ldmst(&(MODULE_EGTM.ADC.OUT[0].U), mask, value);
    }

    /* Configures the adc_out1 selection */
    for (uint32 i = 0; i < handle->app_config->adc_out1.num; i++)
    {
      uint32 shift   = (handle->app_config->adc_out1.conf[i].adc_out1_num & 0x3U) * EGTM_GENERIC_ADC_OUT_SEL_LEN;
      uint32 value   = handle->app_config->adc_out1.conf[i].adc_out1_sel << shift;
      uint32 mask    = 0xFFU << shift;
      Ifx__ldmst(&(MODULE_EGTM.ADC.OUT[1].U), mask, value);
    }

    /* Configures the adc_out2 selection */
    for (uint32 i = 0; i < handle->app_config->adc_out2.num; i++)
    {
      uint32 shift   = (handle->app_config->adc_out2.conf[i].adc_out2_num & 0x3U) * EGTM_GENERIC_ADC_OUT_SEL_LEN;
      uint32 value   = handle->app_config->adc_out2.conf[i].adc_out2_sel << shift;
      uint32 mask    = 0xFFU << shift;
      Ifx__ldmst(&(MODULE_EGTM.ADC.OUT[2].U), mask, value);
    }

    /* Enable HRPWM Modules */
#if IFXEGTM_PWM_IS_HIGH_RES_AVAILABLE
    IfxEgtm_setHrpwmEnable(egtm, IfxEgtm_Hrpwm_0, handle->app_config->hrpwm0_enable);
    IfxEgtm_setHrpwmEnable(egtm, IfxEgtm_Hrpwm_1, handle->app_config->hrpwm1_enable);
    IfxEgtm_setHrpwmEnable(egtm, IfxEgtm_Hrpwm_2, handle->app_config->hrpwm2_enable);
#endif /* #if IFXEGTM_PWM_IS_HIGH_RES_AVAILABLE */

    handle->app_is_initialized = TRUE;
  }

  return EGTM_GENERIC_STATUS_SUCCESS;
}

/* Function to trigger AGC channels host trigger. */
void EGTM_GENERIC_AgcTrigger(EGTM_GENERIC_t *handle, uint32 cluster)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL) && (cluster < EGTM_GENERIC_CLUSTER_NUMBER)));
  Ifx_EGTM *egtm = handle->app_config->egtm_module;

  IfxEgtm_Atom_Agc_trigger(&(egtm->CLS[cluster].ATOM.AGC));
}

/* Function to configure and use time base trigger in AGC. */
void EGTM_GENERIC_AgcTimeTrigger(EGTM_GENERIC_t *handle, uint32 cluster, IfxEgtm_Tbu_Ts base, uint32 value)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL) && (cluster < EGTM_GENERIC_CLUSTER_NUMBER) && (base <= IfxEgtm_Tbu_Ts_2)));
  Ifx_EGTM *egtm = handle->app_config->egtm_module;

  /* IfxEgtm_Tbu_disableChannel */
  uint32 shift = ((uint32)base) << 1U;
  Ifx__ldmst(&egtm->CLS[cluster].TBU.CHEN.U, (uint32)(3u << shift), (uint32)(IfxEgtm_FeatureControl_disable << shift));

  IfxEgtm_Atom_Agc_setTimeTrigger(&(egtm->CLS[cluster].ATOM.AGC), base, value);
  IfxEgtm_Atom_Agc_enableTimeTrigger(&(egtm->CLS[cluster].ATOM.AGC), TRUE);

  /* IfxEgtm_Tbu_setChannelBase */
  if (base == IfxEgtm_Tbu_Ts_0)
  {
    egtm->CLS[cluster].TBU.CH0_BASE.B.BASE = 0;
  }
  else if (base == IfxEgtm_Tbu_Ts_1)
  {
    egtm->CLS[cluster].TBU.CH1.BASE.B.BASE = 0;
  }
  else if (base == IfxEgtm_Tbu_Ts_2)
  {
    egtm->CLS[cluster].TBU.CH2.BASE.B.BASE = 0;
  }

  IfxEgtm_Tbu_enableChannel(egtm, cluster, base);
}

/* Function to trigger TGC channels host trigger. */
void EGTM_GENERIC_TgcTrigger(EGTM_GENERIC_t *handle, uint32 cluster, uint32 tgcno)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL) && (cluster < EGTM_GENERIC_CLUSTER_NUMBER) && (tgcno <= 1)));
  Ifx_EGTM *egtm = handle->app_config->egtm_module;
  Ifx_EGTM_CLS_TOM_TGC *tgc;

  if (tgcno == 0)
  {
    tgc = &(egtm->CLS[cluster].TOM.TGC[0]);
  }
  else
  {
    tgc = &(egtm->CLS[cluster].TOM.TGC[1]);
  }
  IfxEgtm_Tom_Tgc_trigger(tgc);
}

/* Function to configure and use time base trigger in TGC. */
void EGTM_GENERIC_TgcTimeTrigger(EGTM_GENERIC_t *handle, uint32 cluster, uint32 tgcno, IfxEgtm_Tbu_Ts base, uint32 value)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL) && (cluster < EGTM_GENERIC_CLUSTER_NUMBER) && (tgcno <= 1) && (base <= IfxEgtm_Tbu_Ts_2)));
  Ifx_EGTM *egtm = handle->app_config->egtm_module;
  Ifx_EGTM_CLS_TOM_TGC *tgc;

  if (tgcno == 0)
  {
    tgc = &(egtm->CLS[cluster].TOM.TGC[0]);
  }
  else
  {
    tgc = &(egtm->CLS[cluster].TOM.TGC[1]);
  }

  /* IfxEgtm_Tbu_disableChannel */
  uint32 shift = ((uint32)base) << 1U;
  Ifx__ldmst(&egtm->CLS[cluster].TBU.CHEN.U, (uint32)(3u << shift), (uint32)(IfxEgtm_FeatureControl_disable << shift));

  IfxEgtm_Tom_Tgc_setTimeTrigger(tgc, base, value);
  IfxEgtm_Tom_Tgc_enableTimeTrigger(tgc, TRUE);

  /* IfxEgtm_Tbu_setChannelBase */
  if (base == IfxEgtm_Tbu_Ts_0)
  {
    egtm->CLS[cluster].TBU.CH0_BASE.B.BASE = 0;
  }
  else if (base == IfxEgtm_Tbu_Ts_1)
  {
    egtm->CLS[cluster].TBU.CH1.BASE.B.BASE = 0;
  }
  else if (base == IfxEgtm_Tbu_Ts_2)
  {
    egtm->CLS[cluster].TBU.CH2.BASE.B.BASE = 0;
  }

  IfxEgtm_Tbu_enableChannel(egtm, cluster, base);
}

